import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  db.exec('CREATE TABLE b (data BLOB)');
  const put = db.prepare('INSERT INTO b VALUES (?)');
  put.run(new Uint8Array([0, 1, 254, 255]));
  put.run(new Uint8Array(0));
  const rows: any[] = db.prepare('SELECT data, typeof(data) AS t FROM b ORDER BY rowid').all();
  console.log(Array.from(rows[0].data).join(','), rows[0].t);
  console.log(rows[1].data.length, rows[1].t);
  console.log(db.prepare("SELECT typeof(x'') AS t").get().t);
  db.close();
}
